def _cmd_log_filter(
    log_path, start_token, end_token, applied_token,
    max_log_bytes, max_output_bytes,
):
    # START/END 为 * 或任意长度非负整数（按数学整数比较）；均非 * 时
    # START≤END；APPLIED 取 */true/false，否则 usage
